CREATE TABLE "User" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT NOT NULL,"avatarUrl" TEXT NOT NULL DEFAULT '',"username" TEXT NOT NULL,"bio" TEXT NOT NULL DEFAULT '',"location" TEXT NOT NULL DEFAULT '',"website" TEXT NOT NULL DEFAULT '',"passwordHash" TEXT NOT NULL,"passwordSalt" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "User_phone_key" ON "User"("phone"); CREATE UNIQUE INDEX "User_username_key" ON "User"("username");
CREATE TABLE "Session" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Session_pkey" PRIMARY KEY ("id")); CREATE INDEX "Session_userId_idx" ON "Session"("userId");
CREATE TABLE "OtpChallenge" ("id" TEXT NOT NULL,"phone" TEXT NOT NULL,"codeHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"attempts" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"userId" TEXT,CONSTRAINT "OtpChallenge_pkey" PRIMARY KEY ("id")); CREATE INDEX "OtpChallenge_phone_expiresAt_idx" ON "OtpChallenge"("phone","expiresAt");
CREATE TABLE "Conversation" ("id" TEXT NOT NULL,"ownerId" TEXT,"groupName" TEXT,"isGroup" BOOLEAN NOT NULL DEFAULT false,"tripId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Conversation_pkey" PRIMARY KEY ("id")); CREATE INDEX "Conversation_ownerId_idx" ON "Conversation"("ownerId");
CREATE TABLE "ConversationMember" ("conversationId" TEXT NOT NULL,"userId" TEXT NOT NULL,"unreadCount" INTEGER NOT NULL DEFAULT 0,"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ConversationMember_pkey" PRIMARY KEY ("conversationId","userId")); CREATE INDEX "ConversationMember_userId_idx" ON "ConversationMember"("userId");
CREATE TABLE "Message" ("id" TEXT NOT NULL,"conversationId" TEXT NOT NULL,"senderUserId" TEXT NOT NULL,"recipientUserId" TEXT,"kind" TEXT NOT NULL,"text" TEXT,"mediaUrl" TEXT,"fileName" TEXT,"latitude" DOUBLE PRECISION,"longitude" DOUBLE PRECISION,"inviteJson" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Message_pkey" PRIMARY KEY ("id")); CREATE INDEX "Message_conversationId_createdAt_idx" ON "Message"("conversationId","createdAt"); CREATE INDEX "Message_recipientUserId_idx" ON "Message"("recipientUserId");
CREATE TABLE "JourneyMemory" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"year" INTEGER NOT NULL,"date" TEXT NOT NULL,"place" TEXT NOT NULL,"thoughts" TEXT NOT NULL,"images" JSONB NOT NULL,"videos" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "JourneyMemory_pkey" PRIMARY KEY ("id")); CREATE INDEX "JourneyMemory_userId_year_date_idx" ON "JourneyMemory"("userId","year","date");
CREATE TABLE "Wallet" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"tripId" TEXT NOT NULL,"savedAmount" DOUBLE PRECISION NOT NULL DEFAULT 0,"targetAmount" DOUBLE PRECISION NOT NULL DEFAULT 0,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Wallet_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Wallet_userId_tripId_key" ON "Wallet"("userId","tripId");
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "OtpChallenge" ADD CONSTRAINT "OtpChallenge_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ConversationMember" ADD CONSTRAINT "ConversationMember_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "Conversation"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ConversationMember" ADD CONSTRAINT "ConversationMember_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Message" ADD CONSTRAINT "Message_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "Conversation"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Message" ADD CONSTRAINT "Message_senderUserId_fkey" FOREIGN KEY ("senderUserId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "JourneyMemory" ADD CONSTRAINT "JourneyMemory_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Wallet" ADD CONSTRAINT "Wallet_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
